    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
    CHECK_EQ(raw, 0);
    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
    CHECK_EQ(raw, 120);

    gt_light_close(s);
