    do {                                                                \
        long long check_a_ = (long long)(a);                            \
        long long check_b_ = (long long)(b);                            \
        if (check_a_ != check_b_) {                                     \
            fprintf(stderr, "%s:%d: CHECK_EQ failed: %s == %s "         \
