 * Retried after a 10 ms gap and the read succeeds. */
static void test_lsr06_read_retry_recovers(void)
{
    fake_i2c f;
    gt_light_sensor *s = open_on(&f);
    const uint8_t data[] = { 0x01, 0x2C };
    fake_i2c_push_read(&f, data, sizeof data);
